    14→/**
    15→ * 배치 프리뷰 액터
    16→ * 마우스를 따라다니며 유효/무효 색상을 표시
    17→ */
    18→UCLASS()
    19→class WJWORLD_API AWjWorldPlacementPreviewActor : public AActor
    20→{
    21→	GENERATED_BODY()
    22→
    23→public:
    24→	AWjWorldPlacementPreviewActor();
    25→
    26→	/** 오브젝트 정의로 프리뷰 초기화 (메시 비동기 로드) */
    27→	void InitializePreview(const FPlaceableObjectDefinition& Definition);
    28→
    29→	/** 프리뷰 위치/회전 갱신 */
    30→	void UpdatePreviewTransform(const FVector& Location, const FRotator& Rotation);
    31→
    32→	/** 유효/무효 색상 전환 */
    33→	void SetPreviewValid(bool bInIsValid);
    34→
    35→	/** Yaw 회전 누적 */
    36→	void RotatePreview(float DeltaYaw);
    37→
    38→	/** 현재 Yaw 값 */
    39→	float GetCurrentYaw() const { return CurrentYaw; }
    40→
    41→	/** 유효 상태 */
    42→	bool IsPreviewValid() const { return bIsValid; }
    43→
    44→protected:
    45→	UPROPERTY(VisibleAnywhere)
    46→	TObjectPtr<UStaticMeshComponent> PreviewMeshComponent;
    47→
    48→	UPROPERTY()
    49→	TObjectPtr<UMaterialInstanceDynamic> DynamicMaterial;
    50→
    51→	UPROPERTY(EditDefaultsOnly, Category = "Preview")
    52→	FLinearColor ValidColor = FLinearColor(0.0f, 1.0f, 0.0f, 0.5f);
    53→
    54→	UPROPERTY(EditDefaultsOnly, Category = "Preview")
    55→	FLinearColor InvalidColor = FLinearColor(1.0f, 0.0f, 0.0f, 0.5f);
    56→
    57→	UPROPERTY(EditDefaultsOnly, Category = "Preview")
    58→	float PreviewOpacity = 0.5f;
    59→
    60→private:
    61→	void OnMeshLoaded();
    62→
    63→	FStreamableManager StreamableManager;
    64→	TSharedPtr<FStreamableHandle> MeshLoadHandle;
    65→	float CurrentYaw = 0.0f;
    66→	bool bIsValid = true;
    67→	FVector CachedScale = FVector::OneVector;
    68→};
