    26→
    27→void UWjWorldPlacementComponent::EnterPlacementMode()
    28→{
    29→	// 기본 컨텍스트: Lobby
    30→	EnterPlacementModeWithContext(EPlacementContext::Lobby);
    31→}
    32→
    33→void UWjWorldPlacementComponent::EnterPlacementModeWithContext(EPlacementContext Context)
    34→{
    35→	if (CurrentMode != EPlacementMode::None)
    36→	{
    37→		return;
    38→	}
    39→
    40→	CurrentContext = Context;
    41→
    42→	// DeveloperSettings에서 입력 설정 및 Catalog 로드 (컨텍스트별)
    43→	LoadInputSettings();
    44→	EnsureCatalogLoaded();
    45→
    46→	CurrentMode = EPlacementMode::Placing;
    47→	SetComponentTickEnabled(true);
    48→	BindInputActions();
    49→
    50→	OnPlacementModeChanged.Broadcast(CurrentMode);
    51→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Entered placement mode (Context: %s)"),
    52→		*GetPlacementContextName(CurrentContext));
    53→}
    54→
    55→void UWjWorldPlacementComponent::ExitPlacementMode()
    56→{
    57→	if (CurrentMode == EPlacementMode::None)
    58→	{
    59→		return;
    60→	}
    61→
    62→	// 호버 하이라이트 해제
    63→	if (HoveredObject)
    64→	{
    65→		HoveredObject->SetHighlighted(false);
    66→		HoveredObject = nullptr;
    67→	}
    68→
    69→	DestroyPreview();
    70→	UnbindInputActions();
    71→	SetComponentTickEnabled(false);
    72→
    73→	SelectedObjectId = NAME_None;
    74→	CurrentMode = EPlacementMode::None;
    75→	bAirPlacementMode = false;
    76→	AirPlaneHeight = 0.f;
    77→	// 컨텍스트는 리셋하지 않음 (다음 EnterPlacementMode 시 설정)
    78→
    79→	OnPlacementModeChanged.Broadcast(CurrentMode);
    80→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Exited placement mode"));
    81→}
    82→
    83→void UWjWorldPlacementComponent::ToggleDeleteMode()
    84→{
    85→	if (CurrentMode == EPlacementMode::None)
    86→	{
    87→		return;
    88→	}
    89→
    90→	if (CurrentMode == EPlacementMode::Deleting)
    91→	{
    92→		// 삭제 모드 해제 → 배치 모드 복귀
    93→		if (HoveredObject)
    94→		{
    95→			HoveredObject->SetHighlighted(false);
    96→			HoveredObject = nullptr;
    97→		}
    98→		CurrentMode = EPlacementMode::Placing;
    99→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to placing mode"));
   100→	}
   101→	else
   102→	{
   103→		// 배치 모드 → 삭제 모드
   104→		DestroyPreview();
   105→		CurrentMode = EPlacementMode::Deleting;
   106→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to delete mode"));
   107→	}
   108→
   109→	OnPlacementModeChanged.Broadcast(CurrentMode);
   110→}
