   167→void UWjWorldPlacementComponent::ConfirmPlacement()
   168→{
   169→	if (CurrentMode != EPlacementMode::Placing || !PreviewActor || !bCurrentPreviewValid)
   170→	{
   171→		return;
   172→	}
   173→
   174→	if (!Catalog)
   175→	{
   176→		return;
   177→	}
   178→
   179→	const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(SelectedObjectId);
   180→	if (!Def)
   181→	{
   182→		return;
   183→	}
   184→
   185→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   186→	if (!DataProvider)
   187→	{
   188→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: PlacementDataProvider not found"));
   189→		return;
   190→	}
   191→
   192→	// 배치 데이터 생성
   193→	FVector SpawnLocation = PreviewActor->GetActorLocation();
   194→	FRotator SpawnRotation = FRotator(0.0f, PreviewActor->GetCurrentYaw(), 0.0f);
   195→
   196→	FPlacedObjectSaveEntry Entry;
   197→	Entry.ObjectId = SelectedObjectId;
   198→	Entry.Transform = FTransform(SpawnRotation, SpawnLocation, Def->DefaultScale);
   199→
   200→	// DataProvider에 추가 (서버에서 스폰 + 클라이언트 리플리케이션)
   201→	DataProvider->AddPlacedObject(Entry);
   202→
   203→	// 로컬 SaveGame에도 저장 (호스트 영구 저장용)
   204→	SaveLayout();
   205→
   206→	OnObjectPlaced.Broadcast();
   207→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Object placed - ObjectId=%s at %s (Context: %s)"),
   208→		*SelectedObjectId.ToString(), *SpawnLocation.ToString(), *GetPlacementContextName(CurrentContext));
   209→}
