   211→void UWjWorldPlacementComponent::DeleteHoveredObject()
   212→{
   213→	if (CurrentMode != EPlacementMode::Deleting || !HoveredObject)
   214→	{
   215→		return;
   216→	}
   217→
   218→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   219→	if (!DataProvider)
   220→	{
   221→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: PlacementDataProvider not found"));
   222→		return;
   223→	}
   224→
   225→	// DataProvider에서 해당 오브젝트 인덱스 찾기
   226→	int32 Index = FindPlacedObjectIndex(HoveredObject);
   227→	if (Index == INDEX_NONE)
   228→	{
   229→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Could not find object index for deletion"));
   230→		return;
   231→	}
   232→
   233→	HoveredObject = nullptr;
   234→
   235→	// DataProvider에서 제거 (서버에서 파괴 + 클라이언트 리플리케이션)
   236→	DataProvider->RemovePlacedObjectAt(Index);
   237→
   238→	// 로컬 SaveGame에도 저장
   239→	SaveLayout();
   240→
   241→	OnObjectDeleted.Broadcast();
   242→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Object deleted at index %d"), Index);
