   250→void UWjWorldPlacementComponent::SaveLayout()
   251→{
   252→	// 호스트(ListenServer 또는 Standalone)인 경우에만 SaveGame 저장
   253→	// 클라이언트가 저장하면 다른 세션의 배치물이 섞이는 문제 발생
   254→	UWorld* World = GetWorld();
   255→	if (!World)
   256→	{
   257→		return;
   258→	}
   259→
   260→	ENetMode NetMode = World->GetNetMode();
   261→	if (NetMode != NM_Standalone && NetMode != NM_ListenServer)
   262→	{
   263→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayout skipped (not host)"));
   264→		return;
   265→	}
   266→
   267→	// DataProvider에서 데이터를 가져와 로컬 SaveGame에 저장 (호스트 영구 저장용)
   268→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   269→	if (!DataProvider)
   270→	{
   271→		return;
   272→	}
   273→
   274→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   275→		UGameplayStatics::CreateSaveGameObject(UWjWorldLayoutSaveGame::StaticClass())
   276→	);
   277→
   278→	if (!SaveGame)
   279→	{
   280→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to create save game object"));
   281→		return;
   282→	}
   283→
   284→	// DataProvider의 배치 데이터 복사
   285→	SaveGame->PlacedObjects = DataProvider->GetPlacedObjects();
   286→
   287→	// 컨텍스트별 SaveSlot 이름 사용
   288→	FString SlotName = GetCurrentSaveSlotName();
   289→	if (UGameplayStatics::SaveGameToSlot(SaveGame, SlotName, 0))
   290→	{
   291→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout saved to '%s' (%d objects)"),
   292→			*SlotName, SaveGame->PlacedObjects.Num());
   293→	}
   294→	else
   295→	{
   296→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to save layout to '%s'"), *SlotName);
   297→	}
   298→}
