   307→void UWjWorldPlacementComponent::SaveLayoutToSlot(const FString& SlotName)
   308→{
   309→	// 호스트(ListenServer 또는 Standalone)인 경우에만 SaveGame 저장
   310→	UWorld* World = GetWorld();
   311→	if (!World)
   312→	{
   313→		return;
   314→	}
   315→
   316→	ENetMode NetMode = World->GetNetMode();
   317→	if (NetMode != NM_Standalone && NetMode != NM_ListenServer)
   318→	{
   319→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayoutToSlot skipped (not host)"));
   320→		return;
   321→	}
   322→
   323→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   324→	if (!DataProvider)
   325→	{
   326→		return;
   327→	}
   328→
   329→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   330→		UGameplayStatics::CreateSaveGameObject(UWjWorldLayoutSaveGame::StaticClass())
   331→	);
   332→
   333→	if (!SaveGame)
   334→	{
   335→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to create save game object"));
   336→		return;
   337→	}
   338→
   339→	// DataProvider의 배치 데이터 복사
   340→	SaveGame->PlacedObjects = DataProvider->GetPlacedObjects();
   341→	SaveGame->SavedContext = CurrentContext;
   342→
   343→	if (UGameplayStatics::SaveGameToSlot(SaveGame, SlotName, 0))
   344→	{
   345→		LoadedSlotName = SlotName;
   346→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout saved to '%s' (%d objects)"),
   347→			*SlotName, SaveGame->PlacedObjects.Num());
   348→
   349→		// AW 컨텍스트인 경우 CSV도 함께 내보내기
   350→		if (CurrentContext == EPlacementContext::ApproachingWall)
   351→		{
   352→			ExportLayoutAsCSV(SlotName);
   353→		}
   354→		// JumpMap 컨텍스트인 경우 CSV도 함께 내보내기
   355→		else if (CurrentContext == EPlacementContext::JumpMap)
   356→		{
   357→			ExportJumpMapLayoutAsCSV(SlotName);
   358→		}
   359→	}
   360→	else
   361→	{
   362→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to save layout to '%s'"), *SlotName);
   363→	}
   364→}
