   439→bool UWjWorldPlacementComponent::DeleteLayoutSlot(const FString& SlotName)
   440→{
   441→	// SaveGame 삭제
   442→	if (!UGameplayStatics::DeleteGameInSlot(SlotName, 0))
   443→	{
   444→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to delete save slot '%s'"), *SlotName);
   445→		return false;
   446→	}
   447→
   448→	// AW 컨텍스트: CSV 파일도 삭제
   449→	if (CurrentContext == EPlacementContext::ApproachingWall)
   450→	{
   451→		FString CSVPath = GetUserWallLayoutDirectory() / SlotName + TEXT(".csv");
   452→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   453→		if (PlatformFile.FileExists(*CSVPath))
   454→		{
   455→			PlatformFile.DeleteFile(*CSVPath);
   456→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   457→		}
   458→	}
   459→	// JumpMap 컨텍스트: CSV 파일도 삭제
   460→	else if (CurrentContext == EPlacementContext::JumpMap)
   461→	{
   462→		FString CSVPath = GetUserJumpMapLayoutDirectory() / SlotName + TEXT(".csv");
   463→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   464→		if (PlatformFile.FileExists(*CSVPath))
   465→		{
   466→			PlatformFile.DeleteFile(*CSVPath);
   467→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   468→		}
   469→	}
   470→
   471→	// 현재 로드된 슬롯이면 초기화
   472→	if (LoadedSlotName == SlotName)
   473→	{
   474→		LoadedSlotName.Empty();
   475→	}
   476→
   477→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted layout slot '%s'"), *SlotName);
   478→	return true;
   479→}
