   481→bool UWjWorldPlacementComponent::ExportLayoutAsCSV(const FString& FileName)
   482→{
   483→	// AW 컨텍스트에서만 동작
   484→	if (CurrentContext != EPlacementContext::ApproachingWall)
   485→	{
   486→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: Only available in ApproachingWall context"));
   487→		return false;
   488→	}
   489→
   490→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   491→	if (!DataProvider)
   492→	{
   493→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: No data provider"));
   494→		return false;
   495→	}
   496→
   497→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   498→	if (PlacedObjects.Num() == 0)
   499→	{
   500→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: No objects to export"));
   501→		return false;
   502→	}
   503→
   504→	// 그리드 설정 (기본값 사용, 추후 설정 가능하게 확장 가능)
   505→	const FApproachingWallGridConfig GridConfig;
   506→	const FVector& BrickSize = GridConfig.BrickSize;
   507→
   508→	// 1. 배치된 오브젝트의 바운딩 박스 계산
   509→	FVector MinBounds(FLT_MAX, FLT_MAX, FLT_MAX);
   510→	FVector MaxBounds(-FLT_MAX, -FLT_MAX, -FLT_MAX);
   511→
   512→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   513→	{
   514→		const FVector& Location = Entry.Transform.GetLocation();
   515→		MinBounds.X = FMath::Min(MinBounds.X, Location.X);
   516→		MinBounds.Y = FMath::Min(MinBounds.Y, Location.Y);
   517→		MaxBounds.X = FMath::Max(MaxBounds.X, Location.X);
   518→		MaxBounds.Y = FMath::Max(MaxBounds.Y, Location.Y);
   519→	}
   520→
   521→	// 2. 그리드 크기 계산 (+1 = 위치 개수, +2 = 양쪽 1셀 패딩)
   522→	int32 GridColumns = FMath::CeilToInt((MaxBounds.X - MinBounds.X) / BrickSize.X) + 1 + 2;
   523→	int32 GridRows = FMath::CeilToInt((MaxBounds.Y - MinBounds.Y) / BrickSize.Y) + 1 + 2;
   524→
   525→	// 최소 크기 보장
   526→	GridColumns = FMath::Max(GridColumns, 3);
   527→	GridRows = FMath::Max(GridRows, 3);
   528→
   529→	// 그리드 원점: MinBounds에서 1칸 앞 (패딩용, 오브젝트가 인덱스 1부터 매핑)
   530→	FVector GridOrigin = MinBounds - FVector(BrickSize.X, BrickSize.Y, 0.0f);
   531→
   532→	// 3. 그리드 초기화 (-1 = Empty)
   533→	TArray<TArray<int32>> Grid;
   534→	Grid.SetNum(GridRows);
   535→	for (int32 Row = 0; Row < GridRows; ++Row)
   536→	{
   537→		Grid[Row].SetNum(GridColumns);
   538→		for (int32 Col = 0; Col < GridColumns; ++Col)
   539→		{
   540→			Grid[Row][Col] = -1;
   541→		}
   542→	}
   543→
   544→	// 4. 오브젝트를 그리드에 매핑 (RoundToInt로 CalculateBrickGridIndex와 일치)
   545→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   546→	{
   547→		const FVector& Location = Entry.Transform.GetLocation();
   548→
   549→		// 월드 좌표 → 그리드 인덱스
   550→		int32 Col = FMath::RoundToInt((Location.X - GridOrigin.X) / BrickSize.X);
   551→		int32 Row = FMath::RoundToInt((Location.Y - GridOrigin.Y) / BrickSize.Y);
   552→
   553→		// 범위 체크
   554→		if (Row >= 0 && Row < GridRows && Col >= 0 && Col < GridColumns)
   555→		{
   556→			int32 BrickTypeValue = ObjectIdToBrickTypeValue(Entry.ObjectId);
   557→			Grid[Row][Col] = BrickTypeValue;
   558→		}
   559→	}
   560→
   561→	// 5. CSV 문자열 생성 (첫 줄에 메타데이터 포함)
   562→	FString CSVContent;
   563→
   564→	// ⭐ 메타데이터 헤더: CenterOffset 저장 (클라이언트 프리뷰 위치 동기화용)
   565→	// CalculateBrickPosition은 CenterOffset을 그리드 중심으로 사용하므로, 그리드 중심 좌표를 저장
   566→	FVector CenterOffset;
   567→	CenterOffset.X = GridOrigin.X + (GridColumns - 1) * 0.5f * BrickSize.X;
   568→	CenterOffset.Y = GridOrigin.Y + (GridRows - 1) * 0.5f * BrickSize.Y;
   569→	CenterOffset.Z = 0.0f;
   570→	CSVContent += FString::Printf(TEXT("#META:CenterOffset:%f,%f,%f\n"),
   571→		CenterOffset.X, CenterOffset.Y, CenterOffset.Z);
   572→
   573→	for (int32 Row = 0; Row < GridRows; ++Row)
   574→	{
   575→		for (int32 Col = 0; Col < GridColumns; ++Col)
   576→		{
   577→			CSVContent += FString::Printf(TEXT("%d"), Grid[Row][Col]);
   578→			if (Col < GridColumns - 1)
   579→			{
   580→				CSVContent += TEXT(",");
   581→			}
   582→		}
   583→		CSVContent += TEXT("\n");
   584→	}
   585→
   586→	// 6. 파일 저장
   587→	FString UserLayoutDir = GetUserWallLayoutDirectory();
   588→
   589→	// 디렉토리 생성
   590→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   591→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   592→	{
   593→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   594→	}
   595→
   596→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   597→
   598→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   599→	{
   600→		LastExportedCSVPath = FilePath;
   601→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportLayoutAsCSV: Exported to '%s' (Grid: %dx%d)"),
   602→			*FilePath, GridColumns, GridRows);
   603→		return true;
   604→	}
   605→	else
   606→	{
