   611→
   612→bool UWjWorldPlacementComponent::ExportJumpMapLayoutAsCSV(const FString& FileName)
   613→{
   614→	if (CurrentContext != EPlacementContext::JumpMap)
   615→	{
   616→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: Only available in JumpMap context"));
   617→		return false;
   618→	}
   619→
   620→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   621→	if (!DataProvider)
   622→	{
   623→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: No data provider"));
   624→		return false;
   625→	}
   626→
   627→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   628→	if (PlacedObjects.Num() == 0)
   629→	{
   630→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: No objects to export"));
   631→		return false;
   632→	}
   633→
   634→	// CSV 생성: 헤더 + 오브젝트 행
   635→	FString CSVContent;
   636→	CSVContent += FString::Printf(TEXT("#META:MapName:%s\n"), *FileName);
   637→	CSVContent += TEXT("ObjectId,PosX,PosY,PosZ,RotPitch,RotYaw,RotRoll,ScaleX,ScaleY,ScaleZ\n");
   638→
   639→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   640→	{
   641→		const FVector& Loc = Entry.Transform.GetLocation();
   642→		const FRotator Rot = Entry.Transform.GetRotation().Rotator();
   643→		const FVector& Scale = Entry.Transform.GetScale3D();
   644→
   645→		CSVContent += FString::Printf(TEXT("%s,%f,%f,%f,%f,%f,%f,%f,%f,%f\n"),
   646→			*Entry.ObjectId.ToString(),
   647→			Loc.X, Loc.Y, Loc.Z,
   648→			Rot.Pitch, Rot.Yaw, Rot.Roll,
   649→			Scale.X, Scale.Y, Scale.Z);
   650→	}
   651→
   652→	// 파일 저장
   653→	FString UserLayoutDir = GetUserJumpMapLayoutDirectory();
   654→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   655→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   656→	{
   657→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   658→	}
   659→
   660→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   661→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   662→	{
   663→		LastExportedCSVPath = FilePath;
   664→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportJumpMapLayoutAsCSV: Exported to '%s' (%d objects)"),
   665→			*FilePath, PlacedObjects.Num());
   666→		return true;
   667→	}
   668→
   669→	UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: Failed to save '%s'"), *FilePath);
   670→	return false;
   671→}
