   746→bool UWjWorldPlacementComponent::TraceGroundUnderMouse(FHitResult& OutHit) const
   747→{
   748→	APlayerController* PC = GetPlayerController();
   749→	if (!PC)
   750→	{
   751→		return false;
   752→	}
   753→
   754→	FVector WorldLocation, WorldDirection;
   755→	if (!PC->DeprojectMousePositionToWorld(WorldLocation, WorldDirection))
   756→	{
   757→		return false;
   758→	}
   759→
   760→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
   761→
   762→	FCollisionQueryParams QueryParams;
   763→	QueryParams.bTraceComplex = false;
   764→	QueryParams.AddIgnoredActor(GetOwner());
   765→	if (PreviewActor)
   766→	{
   767→		QueryParams.AddIgnoredActor(PreviewActor);
   768→	}
   769→
   770→	return GetWorld()->LineTraceSingleByChannel(OutHit, WorldLocation, TraceEnd, ECC_Visibility, QueryParams);
   771→}
   772→
   773→bool UWjWorldPlacementComponent::TraceAirPlane(FVector& OutLocation) const
   774→{
   775→	APlayerController* PC = GetPlayerController();
   776→	if (!PC)
   777→	{
   778→		return false;
   779→	}
   780→
   781→	FVector WorldLoc, WorldDir;
   782→	if (!PC->DeprojectMousePositionToWorld(WorldLoc, WorldDir))
   783→	{
   784→		return false;
   785→	}
   786→
   787→	// Ray-plane intersection: Plane at Z = AirPlaneHeight, Normal = UpVector
   788→	float Denom = FVector::DotProduct(WorldDir, FVector::UpVector);
   789→	if (FMath::Abs(Denom) < KINDA_SMALL_NUMBER)
   790→	{
   791→		return false; // 레이가 평면과 평행
   792→	}
   793→
   794→	float T = (AirPlaneHeight - WorldLoc.Z) / Denom;
   795→	if (T < 0.f || T > MaxAirTraceDistance)
   796→	{
   797→		return false; // 뒤쪽이거나 너무 먼 교차점
   798→	}
   799→
   800→	OutLocation = WorldLoc + WorldDir * T;
   801→	return true;
   802→}
   803→
   804→bool UWjWorldPlacementComponent::IsPlacementLocationValid(const FVector& Location) const
   805→{
   806→	UWorld* World = GetWorld();
   807→	if (!World)
   808→	{
   809→		return false;
   810→	}
   811→
   812→	// AW 컨텍스트: 그리드 스냅 사용 시 더 작은 반경으로 정확히 같은 위치만 체크
   813→	// 일반 컨텍스트: 기존 겹침 반경 사용
   814→	float CheckRadius = (CurrentContext == EPlacementContext::ApproachingWall)
   815→		? GridOverlapCheckRadius
   816→		: OverlapCheckRadius;
   817→
   818→	// 겹침 체크: 기존 배치된 오브젝트와 겹치는지
   819→	TArray<FOverlapResult> Overlaps;
   820→	FCollisionQueryParams QueryParams;
   821→	QueryParams.AddIgnoredActor(GetOwner());
   822→	if (PreviewActor)
   823→	{
   824→		QueryParams.AddIgnoredActor(PreviewActor);
   825→	}
   826→
   827→	FCollisionShape SphereShape = FCollisionShape::MakeSphere(CheckRadius);
   828→	World->OverlapMultiByChannel(Overlaps, Location, FQuat::Identity, ECC_Visibility, SphereShape, QueryParams);
   829→
   830→	for (const FOverlapResult& Overlap : Overlaps)
   831→	{
   832→		if (Cast<AWjWorldPlacedObjectActor>(Overlap.GetActor()))
   833→		{
   834→			return false;
   835→		}
   836→	}
   837→
   838→	return true;
   839→}
   840→
   841→FVector UWjWorldPlacementComponent::SnapToGrid(const FVector& Location) const
   842→{
   843→	// AW 그리드 설정 사용
   844→	const FApproachingWallGridConfig GridConfig;
   845→	const FVector& BrickSize = GridConfig.BrickSize;
   846→
   847→	// 그리드 스냅: 각 축을 BrickSize 단위로 반올림
   848→	FVector SnappedLocation;
   849→	SnappedLocation.X = FMath::RoundToFloat(Location.X / BrickSize.X) * BrickSize.X;
   850→	SnappedLocation.Y = FMath::RoundToFloat(Location.Y / BrickSize.Y) * BrickSize.Y;
   851→	SnappedLocation.Z = Location.Z; // Z축은 스냅하지 않음 (바닥 높이 유지)
   852→
   853→	return SnappedLocation;
   854→}
