   857→{
   858→	APlayerController* PC = GetPlayerController();
   859→	if (!PC)
   860→	{
   861→		return nullptr;
   862→	}
   863→
   864→	FVector WorldLocation, WorldDirection;
   865→	if (!PC->DeprojectMousePositionToWorld(WorldLocation, WorldDirection))
   866→	{
   867→		return nullptr;
   868→	}
   869→
   870→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
   871→
   872→	FHitResult HitResult;
   873→	FCollisionQueryParams QueryParams;
   874→	QueryParams.bTraceComplex = false;
   875→	QueryParams.AddIgnoredActor(GetOwner());
   876→
   877→	if (GetWorld()->LineTraceSingleByChannel(HitResult, WorldLocation, TraceEnd, ECC_Visibility, QueryParams))
   878→	{
   879→		return Cast<AWjWorldPlacedObjectActor>(HitResult.GetActor());
   880→	}
   881→
   882→	return nullptr;
