    44→void AWjWorldPlacedObjectActor::LoadMesh(const FPlaceableObjectDefinition& Definition)
    45→{
    46→	if (!Definition.Mesh.IsNull())
    47→	{
    48→		FSoftObjectPath MeshPath = Definition.Mesh.ToSoftObjectPath();
    49→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacedObjectActor::LoadMesh - Starting async load for ObjectId=%s, Path=%s"),
    50→			*ObjectId.ToString(), *MeshPath.ToString());
    51→
    52→		MeshLoadHandle = StreamableManager.RequestAsyncLoad(
    53→			MeshPath,
    54→			FStreamableDelegate::CreateUObject(this, &AWjWorldPlacedObjectActor::OnMeshLoaded)
    55→		);
    56→
    57→		if (!MeshLoadHandle.IsValid())
    58→		{
    59→			UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacedObjectActor::LoadMesh - RequestAsyncLoad returned invalid handle for ObjectId=%s"), *ObjectId.ToString());
    60→		}
    61→	}
    62→	else
    63→	{
    64→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacedObjectActor: Mesh is null for ObjectId=%s"), *ObjectId.ToString());
    65→	}
    66→}
    67→
    68→void AWjWorldPlacedObjectActor::OnMeshLoaded()
    69→{
    70→	if (!MeshLoadHandle.IsValid())
    71→	{
    72→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacedObjectActor::OnMeshLoaded - MeshLoadHandle is invalid for ObjectId=%s"), *ObjectId.ToString());
    73→		return;
    74→	}
    75→
    76→	if (!MeshLoadHandle->HasLoadCompleted())
    77→	{
    78→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacedObjectActor::OnMeshLoaded - Load not completed for ObjectId=%s"), *ObjectId.ToString());
    79→		return;
    80→	}
    81→
    82→	UStaticMesh* LoadedMesh = Cast<UStaticMesh>(MeshLoadHandle->GetLoadedAsset());
    83→	if (!LoadedMesh)
    84→	{
    85→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacedObjectActor::OnMeshLoaded - LoadedMesh is null for ObjectId=%s (Asset: %s)"),
    86→			*ObjectId.ToString(),
    87→			*MeshLoadHandle->GetDebugName());
    88→		return;
    89→	}
    90→
    91→	if (!MeshComponent)
    92→	{
    93→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacedObjectActor::OnMeshLoaded - MeshComponent is null for ObjectId=%s"), *ObjectId.ToString());
    94→		return;
    95→	}
    96→
    97→	MeshComponent->SetStaticMesh(LoadedMesh);
    98→	MeshComponent->SetWorldScale3D(CachedScale);
    99→
   100→	// 가시성 명시적으로 활성화
   101→	MeshComponent->SetVisibility(true);
   102→	MeshComponent->SetHiddenInGame(false);
   103→
   104→	// 머티리얼 체크
   105→	int32 NumMaterials = MeshComponent->GetNumMaterials();
   106→	FString MaterialInfo = FString::Printf(TEXT("NumMaterials=%d"), NumMaterials);
   107→	for (int32 i = 0; i < NumMaterials; ++i)
   108→	{
   109→		UMaterialInterface* Mat = MeshComponent->GetMaterial(i);
   110→		MaterialInfo += FString::Printf(TEXT(", Mat[%d]=%s"), i, Mat ? *Mat->GetName() : TEXT("NULL"));
   111→	}
   112→
   113→	// 추가 디버깅: 가시성 및 바운드 확인
   114→	FBoxSphereBounds Bounds = MeshComponent->Bounds;
   115→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacedObjectActor::OnMeshLoaded - SUCCESS for ObjectId=%s, MeshName=%s, Scale=%s, BoundsExtent=%s, Visible=%d, HiddenInGame=%d, %s"),
   116→		*ObjectId.ToString(),
   117→		*LoadedMesh->GetName(),
   118→		*CachedScale.ToString(),
   119→		*Bounds.BoxExtent.ToString(),
   120→		MeshComponent->IsVisible(),
   121→		IsHidden(),
   122→		*MaterialInfo);
   123→}
