    21→void AWjWorldPlacementPreviewActor::InitializePreview(const FPlaceableObjectDefinition& Definition)
    22→{
    23→	CachedScale = Definition.DefaultScale;
    24→
    25→	// 메시 비동기 로드
    26→	if (!Definition.Mesh.IsNull())
    27→	{
    28→		MeshLoadHandle = StreamableManager.RequestAsyncLoad(
    29→			Definition.Mesh.ToSoftObjectPath(),
    30→			FStreamableDelegate::CreateUObject(this, &AWjWorldPlacementPreviewActor::OnMeshLoaded)
    31→		);
    32→	}
    33→	else
    34→	{
    35→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementPreviewActor: Mesh is null for object"));
    36→	}
    37→}
    38→
    39→void AWjWorldPlacementPreviewActor::OnMeshLoaded()
    40→{
    41→	if (MeshLoadHandle.IsValid() && MeshLoadHandle->HasLoadCompleted())
    42→	{
    43→		UStaticMesh* LoadedMesh = Cast<UStaticMesh>(MeshLoadHandle->GetLoadedAsset());
    44→		if (LoadedMesh && PreviewMeshComponent)
    45→		{
    46→			PreviewMeshComponent->SetStaticMesh(LoadedMesh);
    47→			PreviewMeshComponent->SetWorldScale3D(CachedScale);
    48→
    49→			// 동적 머티리얼 생성
    50→			DynamicMaterial = PreviewMeshComponent->CreateAndSetMaterialInstanceDynamic(0);
    51→			if (DynamicMaterial)
    52→			{
    53→				DynamicMaterial->SetScalarParameterValue(TEXT("Opacity"), PreviewOpacity);
    54→				SetPreviewValid(bIsValid);
    55→			}
    56→
    57→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementPreviewActor: Mesh loaded successfully"));
    58→		}
    59→	}
    60→}
