    83→void UWjWorldPlacementComponent::ToggleDeleteMode()
    84→{
    85→	if (CurrentMode == EPlacementMode::None)
    86→	{
    87→		return;
    88→	}
    89→
    90→	if (CurrentMode == EPlacementMode::Deleting)
    91→	{
    92→		// 삭제 모드 해제 → 배치 모드 복귀
    93→		if (HoveredObject)
    94→		{
    95→			HoveredObject->SetHighlighted(false);
    96→			HoveredObject = nullptr;
    97→		}
    98→		CurrentMode = EPlacementMode::Placing;
    99→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to placing mode"));
   100→	}
   101→	else
   102→	{
   103→		// 배치 모드 → 삭제 모드
   104→		DestroyPreview();
   105→		CurrentMode = EPlacementMode::Deleting;
   106→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to delete mode"));
   107→	}
   108→
   109→	OnPlacementModeChanged.Broadcast(CurrentMode);
   110→}
