   112→void UWjWorldPlacementComponent::SelectObject(FName ObjectId)
   113→{
   114→	if (!Catalog)
   115→	{
   116→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: No catalog set"));
   117→		return;
   118→	}
   119→
   120→	const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(ObjectId);
   121→	if (!Def)
   122→	{
   123→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: ObjectId=%s not found in catalog"), *ObjectId.ToString());
   124→		return;
   125→	}
   126→
   127→	// 삭제 모드에서 선택하면 배치 모드로 전환
   128→	if (CurrentMode == EPlacementMode::Deleting)
   129→	{
   130→		if (HoveredObject)
   131→		{
   132→			HoveredObject->SetHighlighted(false);
   133→			HoveredObject = nullptr;
   134→		}
   135→		CurrentMode = EPlacementMode::Placing;
   136→		OnPlacementModeChanged.Broadcast(CurrentMode);
   137→	}
   138→
   139→	// 기존 프리뷰 제거 후 새로 생성
   140→	DestroyPreview();
   141→	SelectedObjectId = ObjectId;
   142→
   143→	UWorld* World = GetWorld();
   144→	if (World)
   145→	{
   146→		FActorSpawnParameters SpawnParams;
   147→		SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
   148→		PreviewActor = World->SpawnActor<AWjWorldPlacementPreviewActor>(AWjWorldPlacementPreviewActor::StaticClass(), FVector::ZeroVector, FRotator::ZeroRotator, SpawnParams);
   149→		if (PreviewActor)
   150→		{
   151→			PreviewActor->InitializePreview(*Def);
   152→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Preview created for ObjectId=%s"), *ObjectId.ToString());
   153→		}
   154→	}
   155→}
