   157→void UWjWorldPlacementComponent::RotatePreview()
   158→{
   159→	if (PreviewActor && CurrentMode == EPlacementMode::Placing)
   160→	{
   161→		const FPlaceableObjectDefinition* Def = Catalog ? Catalog->FindByObjectId(SelectedObjectId) : nullptr;
   162→		float SnapDegrees = Def ? Def->RotationSnapDegrees : 90.0f;
   163→		PreviewActor->RotatePreview(SnapDegrees);
   164→	}
   165→}
