   366→bool UWjWorldPlacementComponent::LoadLayoutFromSlot(const FString& SlotName)
   367→{
   368→	UWorld* World = GetWorld();
   369→	if (!World)
   370→	{
   371→		return false;
   372→	}
   373→
   374→	// SaveGame 로드
   375→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   376→		UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   377→	);
   378→
   379→	if (!SaveGame)
   380→	{
   381→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to load layout from '%s'"), *SlotName);
   382→		return false;
   383→	}
   384→
   385→	// 컨텍스트 검증 (다른 컨텍스트의 레이아웃 로드 방지)
   386→	if (SaveGame->SavedContext != EPlacementContext::None && SaveGame->SavedContext != CurrentContext)
   387→	{
   388→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Context mismatch - slot '%s' is for '%s', current context is '%s'"),
   389→			*SlotName, *GetPlacementContextName(SaveGame->SavedContext), *GetPlacementContextName(CurrentContext));
   390→		return false;
   391→	}
   392→
   393→	// DataProvider가 있으면 데이터 설정
   394→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   395→	if (DataProvider)
   396→	{
   397→		// 일괄 설정 (RespawnAllPlacedObjects가 한 번만 호출됨)
   398→		DataProvider->SetPlacedObjects(SaveGame->PlacedObjects);
   399→	}
   400→
   401→	LoadedSlotName = SlotName;
   402→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout loaded from '%s' (%d objects)"),
   403→		*SlotName, SaveGame->PlacedObjects.Num());
   404→	return true;
   405→}
