   407→TArray<FString> UWjWorldPlacementComponent::GetSavedLayoutSlots() const
   408→{
   409→	TArray<FString> SlotNames;
   410→
   411→	// SaveGame 디렉토리에서 모든 .sav 파일 검색
   412→	FString SaveDirectory = FPaths::ProjectSavedDir() / TEXT("SaveGames");
   413→
   414→	IFileManager& FileManager = IFileManager::Get();
   415→	TArray<FString> FoundFiles;
   416→	FileManager.FindFiles(FoundFiles, *SaveDirectory, TEXT("*.sav"));
   417→
   418→	for (const FString& FileName : FoundFiles)
   419→	{
   420→		// .sav 확장자 제거하여 슬롯 이름 추출
   421→		FString SlotName = FPaths::GetBaseFilename(FileName);
   422→
   423→		// SaveGame을 로드하여 컨텍스트 확인
   424→		UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   425→			UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   426→		);
   427→
   428→		if (SaveGame && SaveGame->SavedContext == CurrentContext)
   429→		{
   430→			SlotNames.Add(SlotName);
   431→		}
   432→	}
   433→
   434→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Found %d saved layout slots for context '%s'"),
   435→		SlotNames.Num(), *GetPlacementContextName(CurrentContext));
   436→	return SlotNames;
   437→}
