   451→		FString CSVPath = GetUserWallLayoutDirectory() / SlotName + TEXT(".csv");
   452→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   453→		if (PlatformFile.FileExists(*CSVPath))
   454→		{
   455→			PlatformFile.DeleteFile(*CSVPath);
   456→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   457→		}
   458→	}
   459→	// JumpMap 컨텍스트: CSV 파일도 삭제
   460→	else if (CurrentContext == EPlacementContext::JumpMap)
   461→	{
   462→		FString CSVPath = GetUserJumpMapLayoutDirectory() / SlotName + TEXT(".csv");
