   676→
   677→	if (CurrentMode == EPlacementMode::Placing && PreviewActor)
   678→	{
   679→		const FPlaceableObjectDefinition* Def = Catalog ? Catalog->FindByObjectId(SelectedObjectId) : nullptr;
   680→		float GroundOffset = Def ? Def->GroundOffset : 0.0f;
   681→		FVector PlaceLocation;
   682→		bool bTraceSuccess = false;
   683→
   684→		if (bAirPlacementMode)
   685→		{
   686→			// Air 모드: 수평 평면과 교차
   687→			FVector AirLocation;
   688→			if (TraceAirPlane(AirLocation))
   689→			{
   690→				PlaceLocation = AirLocation + FVector(0.0f, 0.0f, GroundOffset);
   691→				bTraceSuccess = true;
   692→			}
   693→		}
   694→		else
   695→		{
   696→			// Ground 모드: 기존 바닥 트레이스
   697→			FHitResult HitResult;
   698→			if (TraceGroundUnderMouse(HitResult))
   699→			{
   700→				PlaceLocation = HitResult.ImpactPoint + FVector(0.0f, 0.0f, GroundOffset);
   701→				bTraceSuccess = true;
   702→			}
   703→		}
   704→
   705→		if (bTraceSuccess)
   706→		{
   707→			// AW 컨텍스트: 그리드 스냅 적용
   708→			if (CurrentContext == EPlacementContext::ApproachingWall)
   709→			{
   710→				PlaceLocation = SnapToGrid(PlaceLocation);
   711→			}
   712→
   713→			FRotator PlaceRotation = FRotator(0.0f, PreviewActor->GetCurrentYaw(), 0.0f);
   714→			PreviewActor->UpdatePreviewTransform(PlaceLocation, PlaceRotation);
   715→
   716→			// 유효성 검사
   717→			bCurrentPreviewValid = IsPlacementLocationValid(PlaceLocation);
   718→			PreviewActor->SetPreviewValid(bCurrentPreviewValid);
   719→		}
   720→		else
   721→		{
   722→			bCurrentPreviewValid = false;
   723→			PreviewActor->SetPreviewValid(false);
   724→		}
   725→	}
   726→	else if (CurrentMode == EPlacementMode::Deleting)
   727→	{
   728→		// 삭제 모드: 호버 대상 갱신
   729→		AWjWorldPlacedObjectActor* NewHovered = TraceForPlacedObject();
   730→
   731→		if (NewHovered != HoveredObject)
   732→		{
   733→			if (HoveredObject)
   734→			{
   735→				HoveredObject->SetHighlighted(false);
   736→			}
   737→			HoveredObject = NewHovered;
   738→			if (HoveredObject)
   739→			{
   740→				HoveredObject->SetHighlighted(true);
   741→			}
   742→		}
   743→	}
   744→}
