   841→FVector UWjWorldPlacementComponent::SnapToGrid(const FVector& Location) const
   842→{
   843→	// AW 그리드 설정 사용
   844→	const FApproachingWallGridConfig GridConfig;
   845→	const FVector& BrickSize = GridConfig.BrickSize;
   846→
   847→	// 그리드 스냅: 각 축을 BrickSize 단위로 반올림
   848→	FVector SnappedLocation;
   849→	SnappedLocation.X = FMath::RoundToFloat(Location.X / BrickSize.X) * BrickSize.X;
   850→	SnappedLocation.Y = FMath::RoundToFloat(Location.Y / BrickSize.Y) * BrickSize.Y;
   851→	SnappedLocation.Z = Location.Z; // Z축은 스냅하지 않음 (바닥 높이 유지)
   852→
   853→	return SnappedLocation;
   854→}
