  1008→		}
  1009→		if (ScrollAction)
  1010→		{
  1011→			EIC->BindAction(ScrollAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnScrollAction);
  1012→		}
  1013→		if (ToggleAirModeAction)
  1014→		{
  1015→			EIC->BindAction(ToggleAirModeAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnToggleAirModeAction);
