  1147→int32 UWjWorldPlacementComponent::FindPlacedObjectIndex(AWjWorldPlacedObjectActor* Actor) const
  1148→{
  1149→	if (!Actor)
  1150→	{
  1151→		return INDEX_NONE;
  1152→	}
  1153→
  1154→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
  1155→	if (!DataProvider)
  1156→	{
  1157→		return INDEX_NONE;
  1158→	}
  1159→
  1160→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
  1161→	FName TargetId = Actor->GetObjectId();
  1162→	FVector TargetLocation = Actor->GetActorLocation();
  1163→
  1164→	// ObjectId와 위치로 매칭 (동일 ObjectId가 여러 개 있을 수 있으므로 위치도 체크)
  1165→	for (int32 i = 0; i < PlacedObjects.Num(); ++i)
  1166→	{
  1167→		const FPlacedObjectSaveEntry& Entry = PlacedObjects[i];
  1168→		if (Entry.ObjectId == TargetId)
  1169→		{
  1170→			// 위치가 가까우면 매치
  1171→			if (FVector::DistSquared(Entry.Transform.GetLocation(), TargetLocation) < 100.0f)
  1172→			{
  1173→				return i;
  1174→			}
  1175→		}
  1176→	}
  1177→
  1178→	return INDEX_NONE;
  1179→}
