    61→UWjWorldPlaceableObjectDataAsset* UWjWorldDeveloperSettings::GetPlaceableCatalogForContext(EPlacementContext Context) const
    62→{
    63→	TSoftObjectPtr<UWjWorldPlaceableObjectDataAsset> CatalogRef;
    64→
    65→	switch (Context)
    66→	{
    67→	case EPlacementContext::Lobby:
    68→		CatalogRef = LobbyPlaceableCatalog;
    69→		break;
    70→	case EPlacementContext::ApproachingWall:
    71→		CatalogRef = ApproachingWallPlaceableCatalog;
    72→		break;
    73→	case EPlacementContext::JumpMap:
    74→		CatalogRef = JumpMapPlaceableCatalog;
    75→		break;
    76→	default:
    77→		CatalogRef = PlaceableObjectCatalog;
    78→		break;
    79→	}
    80→
    81→	// 컨텍스트별 카탈로그가 없으면 레거시 폴백
    82→	if (CatalogRef.IsNull())
    83→	{
    84→		CatalogRef = PlaceableObjectCatalog;
    85→	}
    86→
    87→	if (CatalogRef.IsNull())
    88→	{
    89→		return nullptr;
    90→	}
    91→
    92→	return CatalogRef.LoadSynchronous();
    93→}
